        if type(n) is not int or n <= 0:
            raise ValueError("n must be a positive integer")

        sys.stdout.flush()
        start = time.time()
        pids = []
        try:
            for index in range(m):
                pid = os.fork()
                if pid == 0:
                    try:
                        self.parallel_compile(n)
                    except Exception:
                        os._exit(1)
                    os._exit(0)
                pids.append(pid)
        except OSError:
            wait_for_children(pids)
