def wait_for_children(pids):
    success = True
    for pid in pids:
        try:
            waited_pid, status = os.waitpid(pid, 0)
        except OSError:
            success = False
        else:
            if not os.WIFEXITED(status):
                success = False
            elif os.WEXITSTATUS(status) != 0:
                success = False
    return success

